mapper.update:
UPDATE chat_message
SET original_content = COALESCE(original_content, content),
    content = #{content},
    edited = 1,
    edited_at = #{editedAt}
WHERE id = #{messageId}
  AND sender_id = #{senderId}
  AND type = 'TEXT'
  AND recalled = 0
  AND create_time >= #{cutoffTime}

UPDATE chat_message
SET recalled = 1,
    recalled_at = #{recalledAt}
WHERE id = #{messageId}
  AND sender_id = #{senderId}
  AND recalled = 0
  AND create_time >= #{cutoffTime}
